mapper.select:
select *
from ticket_order
where user_id=#{userId} and request_key = #{requestKey}

select * from order_item where order_id in
#{orderId}
order by order_id,order_item_id

select * from screening_seat where screening_id = #{screeningId} and screening_seat_id IN
#{screeningSeatId}
order by screening_seat_id for update

mapper.update:
update screening_seat
set inventory_status = 'AVAILABLE', current_order_id = NULL
where current_order_id = #{orderId} and inventory_status = #{expectedInventoryStatus}

update ticket_order
set order_status = 'PAID', paid_at = #{paidAt}
where order_id = #{orderId} and order_status = 'PENDING'

update ticket_order
set order_status = #{targetStatus}, closed_at = #{closedAt}
where order_id = #{orderId} and order_status = 'PENDING'

mapper.select:
select *
from payment_attempt
where order_id = #{orderId} AND request_key = #{requestKey}
